#!/usr/bin/env node
// Generates `src/infrastructure/migrations-manifest.ts` from the contents of `migrations/`.
//
// The Worker bundle has no filesystem, so `/api/ready` cannot count migration files at
// runtime; it compares what the database recorded against this list, embedded at build time.
// The generated file is committed so a plain `pnpm dev`, `pnpm typecheck` or `vitest` run
// never depends on the build having run first; `scripts/build-worker.mjs` and `db:migrate`
// regenerate it.

import { spawnSync } from "node:child_process";
import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
);
const relativeOutput = "src/infrastructure/migrations-manifest.ts";
const outputPath = path.join(repoRoot, relativeOutput);

const files = readdirSync(path.join(repoRoot, "migrations"))
  .filter((name) => name.endsWith(".sql"))
  .sort();

const before = existsSync(outputPath) ? readFileSync(outputPath, "utf8") : null;

writeFileSync(
  outputPath,
  `// generated by scripts/gen-migrations-manifest.mjs — do not edit
export const MIGRATION_FILES = [
${files.map((name) => `  ${JSON.stringify(name)},`).join("\n")}
] as const;
`,
);

// The file is committed, so `oxfmt --check .` (part of `pnpm lint`) has an opinion about it:
// it collapses a short array onto one line and expands a long one. Hand-rolling that rule
// here would drift from `.oxfmtrc.json`, so run the repository's own formatter. A
// production-only install has no oxfmt; the generated file is still valid TypeScript then.
const formatter = path.join(repoRoot, "node_modules", ".bin", "oxfmt");
if (existsSync(formatter)) {
  const formatted = spawnSync(formatter, ["--write", outputPath], {
    cwd: repoRoot,
    stdio: "ignore",
  });
  if (formatted.status !== 0) {
    console.warn(
      `gen-migrations-manifest: oxfmt could not format ${relativeOutput}`,
    );
  }
}

const after = readFileSync(outputPath, "utf8");
const summary = `${files.length} migration${files.length === 1 ? "" : "s"}`;
console.log(
  before === after
    ? `${relativeOutput} up to date (${summary})`
    : `wrote ${relativeOutput} (${summary})`,
);
